package com.arjunren.leave.dto;
import com.arjunren.leave.domain.*; import com.arjunren.leave.entity.*; import jakarta.validation.constraints.*; import java.time.*; import java.util.List;
public final class Dtos{private Dtos(){}public record LoginRequest(@Email@NotBlank String email,@NotBlank@Size(max=72)String password){}public record UserResponse(Long id,String email,String name,Role role){public static UserResponse of(AppUser u){return new UserResponse(u.getId(),u.getEmail(),u.getName(),u.getRole());}}public record TokenResponse(String accessToken,String tokenType,Instant expiresAt,UserResponse user){}public record EmployeeCreate(@NotBlank@Size(max=30)String employeeNumber,@NotBlank@Size(max=120)String name,@Email@NotBlank String email,@NotBlank@Size(min=12,max=72)String password,@NotNull Role role,Long managerId,@NotBlank@Size(max=120)String department,@Min(0)@Max(365)int annualBalance,@Min(0)@Max(365)int sickBalance){}public record EmployeeResponse(Long id,String employeeNumber,Long userId,String name,String email,Role role,Long managerId,String department,int annualBalance,int sickBalance){public static EmployeeResponse of(EmployeeProfile e){return new EmployeeResponse(e.getId(),e.getEmployeeNumber(),e.getUser().getId(),e.getUser().getName(),e.getUser().getEmail(),e.getUser().getRole(),e.getManager()==null?null:e.getManager().getId(),e.getDepartment(),e.getAnnualBalance(),e.getSickBalance());}}public record LeaveCreate(@NotNull LeaveType type,@NotNull LocalDate startDate,@NotNull LocalDate endDate,@NotBlank@Size(max=500)String reason){}public record DecisionRequest(@Size(max=500)String note){}public record LeaveResponse(Long id,Long employeeId,String employeeName,LeaveType type,LocalDate startDate,LocalDate endDate,int totalDays,String reason,LeaveStatus status,String reviewNote,Instant createdAt,Instant updatedAt){public static LeaveResponse of(LeaveRequest l){return new LeaveResponse(l.getId(),l.getEmployee().getId(),l.getEmployee().getUser().getName(),l.getType(),l.getStartDate(),l.getEndDate(),l.getTotalDays(),l.getReason(),l.getStatus(),l.getReviewNote(),l.getCreatedAt(),l.getUpdatedAt());}}public record PageResponse<T>(List<T>items,int page,int size,long totalElements,int totalPages){}
}

